class Figure
{
public:
    void nommer() { std::cout << "Figure" << std::endl; }
    virtual float aire() = 0;
};

class Carre : public Figure
{
    float cote;
public:
    Carre(float c) : cote(c) {}
    float aire() { return cote * cote; }
    void nommer() { std::cout << "Carre" << std::endl; }
};

int main()
{
    Figure f;              // (1)
    Carre c(3);            // (2)
    c.nommer();            // (3)
    std::cout << c.aire(); // (4)
    return 0;
}

