(3) Point<TYPE>     ->  TYPE Point<TYPE>::getAbscisse() const
(4) <TYPE>          ->  float Point<TYPE>::distance(Point<TYPE> p) const

Code complet :

    template <typename TYPE>
    class Point
    {
        TYPE abscisse;
        TYPE ordonnee;
    public:
        TYPE  getAbscisse() const;
        float distance(Point<TYPE> p) const;
    };

    template <typename TYPE>
    TYPE Point<TYPE>::getAbscisse() const
    {
        return abscisse;
    }

    template <typename TYPE>
    float Point<TYPE>::distance(Point<TYPE> p) const
    {
        return sqrt(pow(abscisse - p.abscisse, 2) + pow(ordonnee - p.ordonnee, 2));
    }

